import * as React from 'react'
import { XIcon } from 'lucide-react'
import { Dialog as DialogPrimitive } from 'radix-ui'
import {
  AnimatePresence,
  LayoutGroup,
  motion,
  useReducedMotion,
  type Transition,
} from 'motion/react'
import { useControllableState } from '@radix-ui/react-use-controllable-state'

import { Button } from './primitives/radix/button'
import { cn } from 'cn'

type ExpandableCardContextValue = {
  open: boolean
  cardLayoutId: string
  mediaLayoutId: string
}

const ExpandableCardContext = React.createContext<ExpandableCardContextValue | null>(null)

const expandableCardTransition: Transition = {
  type: 'spring',
  stiffness: 220,
  damping: 30,
  mass: 0.8,
}

function useExpandableCard() {
  const context = React.useContext(ExpandableCardContext)

  if (!context) {
    throw new Error('ExpandableCard components must be used within <ExpandableCard>.')
  }

  return context
}

function ExpandableCard({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  children,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Root>) {
  const layoutGroupId = React.useId()
  const [open = false, setOpen] = useControllableState({
    prop: openProp,
    defaultProp: defaultOpen,
    onChange: onOpenChange,
  })

  return (
    <ExpandableCardContext.Provider
      value={{
        open,
        cardLayoutId: `${layoutGroupId}-card`,
        mediaLayoutId: `${layoutGroupId}-media`,
      }}
    >
      <LayoutGroup id={layoutGroupId}>
        <DialogPrimitive.Root open={open} onOpenChange={setOpen} {...props}>
          {children}
        </DialogPrimitive.Root>
      </LayoutGroup>
    </ExpandableCardContext.Provider>
  )
}

type ExpandableCardTriggerProps = Omit<React.ComponentProps<typeof motion.button>, 'layoutId'>

function ExpandableCardTrigger({
  className,
  transition = expandableCardTransition,
  type = 'button',
  ...props
}: ExpandableCardTriggerProps) {
  const context = useExpandableCard()
  const shouldReduceMotion = useReducedMotion()

  return (
    <DialogPrimitive.Trigger asChild>
      <motion.button
        data-slot="expandable-card-trigger"
        data-state={context.open ? 'open' : 'closed'}
        type={type}
        layoutId={context.cardLayoutId}
        transition={shouldReduceMotion ? { duration: 0 } : transition}
        className={cn(
          'group/expandable-card block w-full max-w-80 cursor-pointer overflow-hidden rounded-2xl border bg-background text-left shadow-sm outline-none',
          'transition-[border-color,box-shadow] duration-200 hover:border-foreground/20 hover:shadow-md',
          'focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background',
          'disabled:pointer-events-none disabled:opacity-50',
          className,
        )}
        {...props}
      />
    </DialogPrimitive.Trigger>
  )
}

type ExpandableCardMediaProps = Omit<React.ComponentProps<typeof motion.span>, 'layoutId'>

function ExpandableCardMedia({
  className,
  transition = expandableCardTransition,
  ...props
}: ExpandableCardMediaProps) {
  const context = useExpandableCard()
  const shouldReduceMotion = useReducedMotion()

  return (
    <motion.span
      data-slot="expandable-card-media"
      layoutId={context.mediaLayoutId}
      transition={shouldReduceMotion ? { duration: 0 } : transition}
      className={cn('block overflow-hidden', className)}
      {...props}
    />
  )
}

type ExpandableCardContentProps = Omit<
  React.ComponentProps<typeof DialogPrimitive.Content>,
  'asChild' | 'forceMount'
> & {
  showCloseButton?: boolean
  closeLabel?: string
  overlayClassName?: string
  transition?: Transition
  /** Portal target for embedded canvases and preview surfaces. */
  portalContainer?: HTMLElement | null
  /** Positions the overlay and dialog within portalContainer instead of the viewport. */
  contained?: boolean
}

function ExpandableCardContent({
  className,
  children,
  showCloseButton = true,
  closeLabel = 'Close',
  overlayClassName,
  transition = expandableCardTransition,
  portalContainer,
  contained = false,
  ...props
}: ExpandableCardContentProps) {
  const context = useExpandableCard()
  const shouldReduceMotion = useReducedMotion()

  return (
    <DialogPrimitive.Portal forceMount container={portalContainer ?? undefined}>
      <AnimatePresence initial={false}>
        {context.open ? (
          <DialogPrimitive.Overlay key="overlay" forceMount asChild>
            <motion.div
              data-slot="expandable-card-overlay"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={{ duration: shouldReduceMotion ? 0 : 0.16, ease: 'easeOut' }}
              className={cn(
                contained ? 'absolute' : 'fixed',
                'inset-0 z-50 bg-background/10 backdrop-blur-sm',
                overlayClassName,
              )}
            />
          </DialogPrimitive.Overlay>
        ) : null}

        {context.open ? (
          <DialogPrimitive.Content key="content" forceMount asChild {...props}>
            <motion.div
              data-slot="expandable-card-content"
              layoutId={context.cardLayoutId}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={shouldReduceMotion ? { duration: 0 } : transition}
              className={cn(
                contained ? 'absolute max-h-[calc(100%-1rem)]' : 'fixed max-h-[90vh]',
                'top-1/2 left-1/2 z-50 w-[calc(100%-1rem)] max-w-3xl -translate-x-1/2 -translate-y-1/2 overflow-hidden rounded-3xl border bg-background shadow-2xl outline-none',
                className,
              )}
            >
              <div
                className={cn(
                  'overflow-y-auto',
                  contained ? 'max-h-[calc(100%-1rem)]' : 'max-h-[90vh]',
                )}
              >
                {children}
              </div>

              {showCloseButton ? (
                <DialogPrimitive.Close asChild>
                  <Button
                    data-slot="expandable-card-close"
                    variant="outline"
                    size="icon"
                    className="absolute top-4 right-4 rounded-full bg-background/80 backdrop-blur"
                  >
                    <XIcon />
                    <span className="sr-only">{closeLabel}</span>
                  </Button>
                </DialogPrimitive.Close>
              ) : null}
            </motion.div>
          </DialogPrimitive.Content>
        ) : null}
      </AnimatePresence>
    </DialogPrimitive.Portal>
  )
}

function ExpandableCardHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="expandable-card-header"
      className={cn('flex flex-col gap-3 p-6', className)}
      {...props}
    />
  )
}

function ExpandableCardTitle({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="expandable-card-title"
      className={cn('text-2xl font-semibold tracking-tight text-foreground', className)}
      {...props}
    />
  )
}

function ExpandableCardDescription({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      data-slot="expandable-card-description"
      className={cn('max-w-2xl text-sm leading-6 text-muted-foreground', className)}
      {...props}
    />
  )
}

function ExpandableCardBody({ className, ...props }: React.ComponentProps<'div'>) {
  return <div data-slot="expandable-card-body" className={cn('px-6 pb-6', className)} {...props} />
}

function ExpandableCardFooter({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="expandable-card-footer"
      className={cn(
        'flex flex-wrap items-center justify-between gap-3 border-t bg-muted/30 px-6 py-4',
        className,
      )}
      {...props}
    />
  )
}

function ExpandableCardClose({ ...props }: React.ComponentProps<typeof DialogPrimitive.Close>) {
  return <DialogPrimitive.Close data-slot="expandable-card-close" {...props} />
}

export {
  ExpandableCard,
  ExpandableCardBody,
  ExpandableCardClose,
  ExpandableCardContent,
  ExpandableCardDescription,
  ExpandableCardFooter,
  ExpandableCardHeader,
  ExpandableCardMedia,
  ExpandableCardTitle,
  ExpandableCardTrigger,
  expandableCardTransition,
}

'use client'

// Copyright (c) 2026 Navdeep Singh. MIT license; see LICENSE.

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { Slot } from 'radix-ui'

import { cn } from 'cn'

const buttonVariants = cva(
  "group/button inline-flex shrink-0 cursor-pointer items-center justify-center rounded-lg border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition-all outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground [a]:hover:bg-primary/80',
        outline:
          'border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary:
          'bg-secondary text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground',
        ghost:
          'hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50',
        destructive:
          'bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40',
        link: 'text-primary underline-offset-4 hover:underline',
      },
      size: {
        default:
          'h-8 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2',
        xs: "h-6 gap-1 rounded-[min(var(--radius-md),10px)] px-2 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-7 gap-1 rounded-[min(var(--radius-md),12px)] px-2.5 text-[0.8rem] in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: 'h-9 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2',
        icon: 'size-8',
        'icon-xs':
          "size-6 rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-lg [&_svg:not([class*='size-'])]:size-3",
        'icon-sm':
          'size-7 rounded-[min(var(--radius-md),12px)] in-data-[slot=button-group]:rounded-lg',
        'icon-lg': 'size-9',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

type ButtonProps = React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }

function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  ...props
}: ButtonProps) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-primitive="radix"
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }
export type { ButtonProps }
